targets.query:
import "date"
from(bucket: "waid-bucket")
  |> range(start: date.sub(d: 5m, from: v.timeRangeStop), stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "mqtt_consumer" and r["_field"] == "total_act_power")
  |> last()
  |> map(fn: (r) => ({
      _time: r._time,
      _value: if r._value < 0.0 then -r._value else r._value,
      _field: if r._value < -30.0 then "Exporting" else if r._value > 30.0 then "Importing" else "Idle"
    }))
